INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(37111, 'Zechariah 4:9', 'Zechariah', 4, 9, '”د زرُبابل لاسونو د خُدائ د کور بنياد کېښودو، هم د دۀ لاسونه به يې مکمل کړى. بيا به تاسو ته پته ولګى چې مالِک خُدائ ربُ الافواج زۀ تاسو ته رالېږلے يم.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_9.mp3', '', 1761754199, 1761754199),
(37112, 'Zechariah 4:10', 'Zechariah', 4, 10, 'وړو شروعاتو ته په سپکه سترګه مۀ ګورئ، ځکه چې هغه د کار په شروع کېدو سره چې د زرُبابل په لاس کښې سال وګورى خوشحاليږى. دا اووۀ ډيوې د مالِک خُدائ د سترګو نمائندګى کوى، چې د هغوئ په ذريعه د ټولې دُنيا لټون کوى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_10.mp3', '', 1761754199, 1761754199),
(37113, 'Zechariah 4:11', 'Zechariah', 4, 11, 'بيا ما د فرښتې نه تپوس وکړو، ”دا د زيتُونو دوه ونې څۀ دى چې د ډيوټ ښې او ګس طرف ته دى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_11.mp3', '', 1761754199, 1761754199),
(37114, 'Zechariah 4:12', 'Zechariah', 4, 12, 'او بيا ما هغې نه تپوس وکړو، ”دا دوه د زيتُونو څانګې چې د سرو زرو دوه نلکو په خوا کښې دى چې ترې تېل بهيږى دا څۀ دى؟“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_12.mp3', '', 1761754199, 1761754199),
(37115, 'Zechariah 4:13', 'Zechariah', 4, 13, 'هغې جواب راکړو، ”آيا تا ته پته نشته چې دا څۀ دى؟“ ”نه، مالِکه،“ ما ورته ووئيل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_13.mp3', '', 1761754199, 1761754199),
(37116, 'Zechariah 4:14', 'Zechariah', 4, 14, 'نو هغې وفرمائيل، ”دا دوه غوره شوى سړى دى چې د ټولې دُنيا د مالِک خِدمت وکړى.“', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zechariah4_verse_14.mp3', '', 1761754199, 1761754199),
(37117, 'Psalms 56:1', 'Psalms', 56, 1, 'په ما رحم وکړه خدایه ځکه خلک راپسې دي خپل دښمنان ما همېشه ځوروي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_1.mp3', '', 1761754199, 1761754199),
(37118, 'Psalms 56:2', 'Psalms', 56, 2, 'زما دښمنان دي راپسې ټوله ورځ کوي بریدونه په ما ډېر خلک په غرور سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_2.mp3', '', 1761754199, 1761754199),
(37119, 'Psalms 56:3', 'Psalms', 56, 3, 'کله چې ووېرېږم نو زه به تا باندې توکل وکړمه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_3.mp3', '', 1761754199, 1761754199),
(37120, 'Psalms 56:4', 'Psalms', 56, 4, 'کوم ستاینه زه د خدای د وعدو زه توکل کړم په هغه او نه وېرېږمه زه فاني انسان څه شي کولای په ما؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_4.mp3', '', 1761754199, 1761754199),
(37121, 'Psalms 56:5', 'Psalms', 56, 5, 'زما دښمنان بدلوي ټوله ورځ زما خبرې دسیسې تل راجوړوي چې راته زیان ورسي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_5.mp3', '', 1761754199, 1761754199),
(37122, 'Psalms 56:6', 'Psalms', 56, 6, 'پټو ځایو کې راټولیږي هغوی څارنه کړي زما د هر حرکت په دې امید کې دي چې ومې وژني', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_6.mp3', '', 1761754199, 1761754199),
(37123, 'Psalms 56:7', 'Psalms', 56, 7, 'بدکاران دي دوی نو مه پرېږده چې تېښته وکړي ته رانسکور کړه د دښمن قومونه په خپل قهر سره', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_7.mp3', '', 1761754199, 1761754199),
(37124, 'Psalms 56:8', 'Psalms', 56, 8, 'تا دي شمېرلې زما ټولې لالهانده ورځې زما د اوښکو حساب تا نیولی د هغوی لست ستا په کتاب کې نشته؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_8.mp3', '', 1761754199, 1761754199),
(37125, 'Psalms 56:9', 'Psalms', 56, 9, 'په هغه ورځ چې تاته وکړم فریاد بېرته په شا به شي زما دښمنان په دې پوهېږمه زه ځکه چې خدای دی ولاړ زما په طرف', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_9.mp3', '', 1761754199, 1761754199),
(37126, 'Psalms 56:10', 'Psalms', 56, 10, 'کوم ستاینه زه د خدای د وعدو کوم ستاینه د څښتن د وعدو', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_10.mp3', '', 1761754199, 1761754199),
(37127, 'Psalms 56:11', 'Psalms', 56, 11, 'زه توکل کوم په خدای او نه وېرېږمه زه څه کولای شي انسان ما سره؟', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_11.mp3', '', 1761754199, 1761754199),
(37128, 'Psalms 56:12', 'Psalms', 56, 12, 'ما چې منلي دي نذرونه تاته هغه زه پوره کومه خدایه زه به ادا کړم نذرانې د شکرانې تاته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_12.mp3', '', 1761754199, 1761754199),
(37129, 'Psalms 56:13', 'Psalms', 56, 13, 'ځکه چې تا کړمه زه خلاص له مرګه زه دې کړم بچ د تیندکونو څخه نو زه به وګرځم د خدای حضور کې هغې رڼا کې کوم چې خلکو ته ژوندون ورکوي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms56_verse_13.mp3', '', 1761754199, 1761754199),
(37130, 'Joshua 8:1', 'Joshua', 8, 1, 'څښتن یوشع ته وویل: «مه وېرېږه او مه بې زړه کېږه. ټول لښکر د ځان سره واخله او عای ته لاړ شه. زه به تا د عای په پاچا، د هغه په خلکو او ښار باندې بریالی کړم او د هغه خاوره به ستا شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_1.mp3', '', 1761754199, 1761754199),
(37131, 'Joshua 8:2', 'Joshua', 8, 2, 'ته به د عای او د هغه د پاچا سره داسې کار وکړې لکه څنګه چې دې د اریحا او د هغه ځای د پاچا سره وکړ. خو دا ځل تاسو کولای شئ چې د هغوی مالونه او څاروي د خپلو ځانونو دپاره وساتئ. تیار اوسئ چې په ناڅاپي توګه د شا له خوا په ښار باندې حمله وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_2.mp3', '', 1761754199, 1761754199),
(37132, 'Joshua 8:5', 'Joshua', 8, 5, 'زه او پاتې کسان به ښار ته نژدې ورشو. کله چې د عای خلک د مخکې ځل په شان راووځي او په مونږ باندې حمله وکړي، نو مونږ به وتښتو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_5.mp3', '', 1761754199, 1761754199),
(37133, 'Joshua 8:6', 'Joshua', 8, 6, 'هغوی به تر هغې پورې زمونږ پسې شي، ترڅو مونږ هغوی وغولوو چې د ښار څخه لېرې شي، ځکه چې هغوی به فکر وکړي چې مونږ د مخکې په شان د هغوی څخه تښتو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_6.mp3', '', 1761754199, 1761754199),
(37134, 'Joshua 8:7', 'Joshua', 8, 7, 'بیا به تاسو د هغه پټ ځای څخه راووځئ او ښار به ونیسئ. زمونږ څښتن خدای به هغه ښار تاسو ته درکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_7.mp3', '', 1761754199, 1761754199),
(37135, 'Joshua 8:8', 'Joshua', 8, 8, 'لکه څنګه چې څښتن حکم کړی دی د ښار د نیولو څخه وروسته هغه ته اور ورواچوئ. د دې امرونو څخه په کلکه اطاعت وکړئ.»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_8.mp3', '', 1761754199, 1761754199),
(37136, 'Joshua 8:9', 'Joshua', 8, 9, 'نو یوشع هغوی رخصت کړل او هغوی خپل د پټېدلو ځای ته لاړل یعنې د عای لوېدیځ خواته چې د بیت ییل او عای ترمنځ ؤ او هلته یې انتظار کاوه. خو یوشع شپه په کمپ کې تېره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_9.mp3', '', 1761754199, 1761754199),
(37137, 'Joshua 8:10', 'Joshua', 8, 10, 'سبا ته سهار وختي یوشع پاڅېده او عسکر یې سره راټول کړل. بیا هغه او د اسراییلو مشرانو تر عای پورې د هغوی لارښوونه وکړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_10.mp3', '', 1761754199, 1761754199),
(37138, 'Joshua 8:11', 'Joshua', 8, 11, 'هغه د ټولو عسکرو سره د ښار د اصلي دروازې خواته لاړ او په شمال کې یې خېمې ودرولې. د هغوی او عای ترمنځ یوه دره وه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_11.mp3', '', 1761754199, 1761754199),
(37139, 'Joshua 8:12', 'Joshua', 8, 12, 'هغه نژدې پنځه زره کسان بوتلل چې د ښار په لوېدیځ کې د عای او بیت ییل ترمنځ کمین ونیسي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_12.mp3', '', 1761754199, 1761754199),
(37140, 'Joshua 8:13', 'Joshua', 8, 13, 'عسکر د جګړې دپاره تیار کړای شول. اصلي کمپ د ښار په شمال کې ؤ او پاتې کسان په لوېدیځ کې وو. یوشع شپه په دره کې تېره کړه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_13.mp3', '', 1761754199, 1761754199),
(37141, 'Joshua 8:14', 'Joshua', 8, 14, 'کله چې د عای پاچا د یوشع کسان ولیدل، نو هغه زر لاس په کار شو. هغه د خپلو ټولو کسانو سره د اردن د درې خواته روان شو چې هلته د اسراییلیانو سره وجنګیږي، خو هغه نه پوهېده چې د شا له خوا به ورباندې حمله وشي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_14.mp3', '', 1761754199, 1761754199),
(37142, 'Joshua 8:15', 'Joshua', 8, 15, 'یوشع د خپلو کسانو سره داسې وښودله چې ګوندې هغوی په شا شول او د دښتې خواته وتښتېدل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_15.mp3', '', 1761754199, 1761754199),
(37143, 'Joshua 8:16', 'Joshua', 8, 16, 'د ښار په ټولو خلکو باندې غږ وشو چې په اسراییلیانو پسې روان شي. څنګه چې د عای خلک په هغوی پسې لاړل، نو اسراییلیانو هغوی وغولول او د ښار څخه یې لېرې کړل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_16.mp3', '', 1761754199, 1761754199),
(37144, 'Joshua 8:17', 'Joshua', 8, 17, 'په عای یا بیت ییل کې چې هرڅوک ؤ هغه ټول په اسراییلیانو پسې روان شول. هلته هېڅوک پاتې نه شو چې د ښار څخه دفاع وکړي او د ښار دروازې خلاصې پاتې شوې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_17.mp3', '', 1761754199, 1761754199),
(37145, 'Joshua 8:18', 'Joshua', 8, 18, 'بیا څښتن یوشع ته وویل: «خپله نېزه د عای خواته ونیسه، ځکه چې هغه تاته درکوم.» نو څنګه چې یوشع ته ویل شوي وو هغه هماغسې وکړل', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_18.mp3', '', 1761754199, 1761754199),
(37146, 'Joshua 8:19', 'Joshua', 8, 19, 'او څنګه چې هغه خپله نېزه پورته کړه، کوم کسان چې پټ وو هغوی زر د خپلو ځایونو څخه پاڅېدل، ښار ته په منډه ورننوتل او هغه یې ونیوه. هغوی سمدلاسه ښار ته اور واچاوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_19.mp3', '', 1761754199, 1761754199),
(37147, 'Joshua 8:22', 'Joshua', 8, 22, 'نو هغه اسراییلیان چې په ښار کې وو په جګړه کې د برخې اخیستلو دپاره راښکته شول. نو د عای خلکو ولیدل چې اسراییلیانو هغوی بیخي کلابند کړي دي او هغوی ټول ووژل شول. هېڅوک ونه تښتېده او نه څوک ژوندی پاتې شو،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_22.mp3', '', 1761754199, 1761754199),
(37148, 'Joshua 8:23', 'Joshua', 8, 23, 'پرته د عای د پاچا څخه. هغه ژوندی ونیول شو او یوشع ته راوړل شو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_23.mp3', '', 1761754199, 1761754199),
(37149, 'Joshua 8:24', 'Joshua', 8, 24, 'کله چې اسراییلیانو هغه ټول خلک چې په دښته کې وو او هلته یې هغوی تعقیب کړي وو، ووژل، نو بیا ټول اسراییلیان د عای ښار ته ورغلل او د هغه ځای ټول خلک یې ووژل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_24.mp3', '', 1761754199, 1761754199),
(37150, 'Joshua 8:27', 'Joshua', 8, 27, 'لکه څنګه چې څښتن یوشع ته ویلي وو، هغوی هغه څاروي او مالونه چې په ښار کې یې نیولي وو د خپلو ځانونو دپاره وساتل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_27.mp3', '', 1761754199, 1761754199),
(37151, 'Joshua 8:28', 'Joshua', 8, 28, 'نو یوشع عای وسوځاوه او په کنډواله یې بدل کړ. هغه ځای تر نن ورځې پورې هماغسې پاتې دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_28.mp3', '', 1761754199, 1761754199),
(37152, 'Joshua 8:29', 'Joshua', 8, 29, 'هغه د عای پاچا په یوې ونې کې ځوړند کړ او د هغه مړی یې تر ماښامه پورې هلته پرېښود. د لمرپرېواته په وخت کې یوشع حکم وکړ چې هغه مړی دې لېرې کړای شي او د ښار د دروازې په خوله کې دې وغورځول شي. هغوی هغه د تیږو په لوی انبار کې پټ کړ چې تر نن ورځې پورې هلته دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_29.mp3', '', 1761754199, 1761754199),
(37153, 'Joshua 8:30', 'Joshua', 8, 30, 'بیا یوشع د عیبال په غره باندې د اسراییلو د څښتن خدای دپاره د قربانۍ ځای جوړ کړ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_30.mp3', '', 1761754199, 1761754199),
(37154, 'Joshua 8:31', 'Joshua', 8, 31, 'هغه یې د هغه حکم سره سم جوړ کړ چې د څښتن خدمتګار موسی اسراییلیانو ته کړی ؤ، لکه څنګه چې د موسی په شریعت کې ویل شوي وو: «د قربانۍ ځای دې د هغو تیږو څخه جوړ شي چې هغه د اوسپنې د سامان الاتو په وسیله پرې کړل شوې نه وي.» په هغه باندې هغوی څښتن ته سوځېدونکې قربانۍ او همدارنګه خپلې د سلامتۍ نذرانې وړاندې کړې.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_31.mp3', '', 1761754199, 1761754199),
(37155, 'Joshua 8:32', 'Joshua', 8, 32, 'یوشع هلته د اسراییلیانو په مخکې په تیږو باندې د موسی د شریعت یو نقل ولیکه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_32.mp3', '', 1761754199, 1761754199),
(37156, 'Joshua 8:33', 'Joshua', 8, 33, 'اسراییلیان د خپلو مشرانو، مامورینو، قاضیانو او هغو پردیو خلکو سره چې د هغوی په منځ کې اوسېدل، د څښتن د لوظ د صندوق دواړو اړخونو ته ودرېدل او هغو لاوي کاهنانو ته مخامخ وو چې صندوق یې وړلو. نیم قوم داسې ولاړ ؤ چې شا یې د جرزیم غره ته وه او نیمایي نورو خپله شا د عیبال غره ته اړولې وه. موسی حکم کړی ؤ چې هغوی دې په همدې ترتیب سره ودریږي او برکت دې اعلان شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_33.mp3', '', 1761754199, 1761754199),
(37157, 'Joshua 8:34', 'Joshua', 8, 34, 'بیا یوشع د موسی د شریعت د کتاب څخه برکتونه او لعنتونه په لوړ اواز سره ولوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_34.mp3', '', 1761754199, 1761754199),
(37158, 'Joshua 8:35', 'Joshua', 8, 35, 'یوشع د اسراییلو ټولې غونډې ته چې په هغوی کې ښځې او ماشومان او هغه پردي خلک چې د هغوی په منځ کې اوسېدل، شامل وو د موسی ټول حکمونه ولوستل.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/joshua8_verse_35.mp3', '', 1761754199, 1761754199),
(37159, 'Deuteronomy 21:1', 'Deuteronomy', 21, 1, 'فرض کړئ د هغه هېواد په یوه ځمکه کې چې خپل څښتن خدای یې تاسو ته درکوي، یو قتل شوی کس موندل کیږي او تاسو نه پوهېږئ چې هغه چا وژلی دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_1.mp3', '', 1761754199, 1761754199),
(37160, 'Deuteronomy 21:2', 'Deuteronomy', 21, 2, 'ستاسو مشران او قاضیان دې لاړ شي او د هغه ځای څخه چې مړی په کې موندل شوی دی تر شاوخوا ښارونو پورې دې فاصله اندازه کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_2.mp3', '', 1761754199, 1761754199),
(37161, 'Deuteronomy 21:3', 'Deuteronomy', 21, 3, 'بیا د هغه ښار مشران چې هغه ځای ته د ټولو نه نژدې وي چې مړی په کې موندل شوی وي، یوه داسې خوسی غوره کړي چې هېڅ کار ورڅخه اخیستل شوی نه وي او جغ ورباندې نه وي ایښودل شوی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_3.mp3', '', 1761754199, 1761754199),
(37162, 'Deuteronomy 21:4', 'Deuteronomy', 21, 4, 'هغوی دې دا خوسی یوې داسې ویالې ته نژدې یو ځای ته ورښکته کړي چې هېڅ نه وچیږي او چېرته چې ځمکه هېڅکله قلبه شوې نه وي او څه په کې کرل شوي نه وي، نو هلته دې هغوی د هغه ورمېږ مات کړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_4.mp3', '', 1761754199, 1761754199),
(37163, 'Deuteronomy 21:5', 'Deuteronomy', 21, 5, 'لاوي کاهنان دې هم هلته لاړ شي، ځکه چې هغوی د هرې قانوني دعوې پرېکړه کوي چې ظلم او زیاتی په کې وي. ستاسو څښتن خدای هغوی د عبادت ځای د ځانګړي خدمت دپاره او د دې دپاره غوره کړي دي چې د هغه په نوم برکت ورکړي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_5.mp3', '', 1761754199, 1761754199),
(37164, 'Deuteronomy 21:6', 'Deuteronomy', 21, 6, 'بیا به د هغه ښار ټول مشران چې هغه ځای ته تر ټولو نژدې وي چې مړی په کې موندل شوی وي، خپل لاسونه د مړ خوسي دپاسه ووینځي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_6.mp3', '', 1761754199, 1761754199),
(37165, 'Deuteronomy 21:7', 'Deuteronomy', 21, 7, 'او داسې اعلان دې وکړي: ‹مونږ دا کس په قتل نه دی رسولی او په دې نه پوهېږو چې چا دا قتل کړی دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_7.mp3', '', 1761754199, 1761754199),
(37166, 'Deuteronomy 21:8', 'Deuteronomy', 21, 8, 'څښتنه، خپل قوم اسراییل چې تا د مصر څخه ازاد کړی دی وبخښه. مونږ وبخښه او د یو بې ګناه کس د قتل مسوولیت زمونږ په غاړه مه اچوه.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_8.mp3', '', 1761754199, 1761754199),
(37167, 'Deuteronomy 21:9', 'Deuteronomy', 21, 9, 'نو تاسو به خپل ځانونه د بې ګناه وینې د تویولو د جرم څخه پاک کړئ، ځکه چې تاسو داسې کار وکړ چې د څښتن په نظر کې سم دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_9.mp3', '', 1761754199, 1761754199),
(37168, 'Deuteronomy 21:10', 'Deuteronomy', 21, 10, 'کله چې تاسو ته خپل څښتن خدای په جګړه کې بری درکړي او تاسو خلک اسیران کړئ،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_10.mp3', '', 1761754199, 1761754199),
(37169, 'Deuteronomy 21:11', 'Deuteronomy', 21, 11, 'نو کېدای شي چې د هغوی په منځ کې یوه داسې ښایسته انجلۍ ووینئ چې ستاسو خوښیږي او غواړئ چې واده ورسره وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_11.mp3', '', 1761754199, 1761754199),
(37170, 'Deuteronomy 21:12', 'Deuteronomy', 21, 12, 'هغه خپل کور ته راولئ. هلته به هغه خپل سر وخرایي، خپل نوکان به پرې کړي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_12.mp3', '', 1761754199, 1761754199),
(37171, 'Deuteronomy 21:13', 'Deuteronomy', 21, 13, 'او خپل د اسیرتوب کالي به وباسي. هغه دې یوه میاشت ستاسو په کور کې پاتې شي او د خپل مور او پلار دپاره دې وژاړي. له هغې وروسته تاسو کولای شئ چې واده ورسره وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_13.mp3', '', 1761754199, 1761754199),
(37172, 'Deuteronomy 21:14', 'Deuteronomy', 21, 14, 'وروسته که چېرې تاسو د هغې سره خوشحاله نه وئ، نو طلاق ورته ورکړئ او هغه پرېږدئ چې هر چېرته چې غواړي لاړه شي. هغه د یوې وینځې په توګه نه شئ خرڅولی او نه یې خپله وینځه جوړولی شئ، ځکه چې تاسو د هغې سره یوځای شوي یئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_14.mp3', '', 1761754199, 1761754199),
(37173, 'Deuteronomy 21:15', 'Deuteronomy', 21, 15, 'فرض کړئ یو سړی دوه ښځې لري چې یوه ورباندې ګرانه وي او بله ورباندې ګرانه نه وي او هغوی دواړه هغه ته زامن وزېږوي، خو مشر زوی یې د هغې ښځې اولاد وي چې د هغه خوښه نه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_15.mp3', '', 1761754199, 1761754199),
(37174, 'Deuteronomy 21:16', 'Deuteronomy', 21, 16, 'کله چې هغه سړی پرېکړه کوي چې څنګه به هغه د خپلو زامنو ترمنځ خپل جایداد ووېشي، نو هغه دې د مشر زوی د برخې په ورکولو سره د خپلې هغې ښځې د زوی طرفداري نه کوي چې هغه یې خوښه ده.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_16.mp3', '', 1761754199, 1761754199),
(37175, 'Deuteronomy 21:17', 'Deuteronomy', 21, 17, 'هغه دې د خپل مال څخه مشر زوی ته دوه چنده برخه ورکړي، که څه هم هغه د هغې ښځې زوی نه دی چې د هغه خوښه ده. یو سړی باید خپل مشر زوی قبول کړي او هغه برخه ورته ورکړي چې هغه یې په قانوني توګه لایق دی.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_17.mp3', '', 1761754199, 1761754199),
(37176, 'Deuteronomy 21:18', 'Deuteronomy', 21, 18, 'فرض کړئ یو سړی یو سرزوری او سرکښ زوی لري، سره د دې چې مور او پلار ورته سزا هم ورکوي، خو د هغوی اطاعت نه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_18.mp3', '', 1761754199, 1761754199),
(37177, 'Deuteronomy 21:19', 'Deuteronomy', 21, 19, 'د هغه مور او پلار دې هغه د ښار دروازې ته چې د ښار مشران غونډه کوي، ورولي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_19.mp3', '', 1761754199, 1761754199),
(37178, 'Deuteronomy 21:20', 'Deuteronomy', 21, 20, 'هغوی دې مشرانو ته داسې ووایي: ‹زمونږ زوی سرزوری او سرکښ دی او زمونږ اطاعت نه کوي، هغه پیسې بېځایه مصرفوي او شرابي دی.›', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_20.mp3', '', 1761754199, 1761754199),
(37179, 'Deuteronomy 21:21', 'Deuteronomy', 21, 21, 'بیا دې د ښار خلک هغه سنګسار کړي چې مړ شي او په دې ډول به تاسو خپل ځانونه د دې بدکارۍ څخه خلاص کړئ. په اسراییلو کې به ټول خلک د دې پېښې څخه خبر شي او وبه وېریږي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_21.mp3', '', 1761754199, 1761754199),
(37180, 'Deuteronomy 21:22', 'Deuteronomy', 21, 22, 'که چېرې یو کس د یو جرم له امله وژل شوی وي او د هغه مړی په یوه ونه کې ځوړند وي،', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_22.mp3', '', 1761754199, 1761754199),
(37181, 'Deuteronomy 21:23', 'Deuteronomy', 21, 23, 'دا مړی باید ټوله شپه هلته پاتې نه شي. هغه باید په هماغه ورځ ښخ شي، ځکه چې یو داسې مړی چې په ونه کې ځوړند وي په وطن باندې د خدای لعنت راولي. نو هغه مړی ښخ کړئ، ترڅو تاسو هغه وطن ناپاکه نه کړئ چې خپل څښتن خدای یې درکوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy21_verse_23.mp3', '', 1761754199, 1761754199),
(37182, 'Psalms 129:1', 'Psalms', 129, 1, 'پرېږده چې قوم د اسراییل ووایي: «هغوی څومره ځورولی یمه خپل دښمنانو د ځوانۍ له وخته', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms129_verse_1.mp3', '', 1761754199, 1761754199),
(37183, 'Psalms 129:2', 'Psalms', 129, 2, 'چې هغوی څومره ځورولی یمه خپل دښمنانو د ځوانۍ له وخته خو دوی په ما بریالي شوي نه دي', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms129_verse_2.mp3', '', 1761754199, 1761754199),
(37184, 'Psalms 129:3', 'Psalms', 129, 3, 'هغوی جوړ کړي دي زخمونه زما په ملا باندې لکه چې څوک وکړي قلبه په ځمکه»', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms129_verse_3.mp3', '', 1761754199, 1761754199),
(37185, 'Psalms 129:4', 'Psalms', 129, 4, 'خو څښتن چې دی عادل او زه یې ازاد کړمه د بدکارانو له رسیو څخه', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms129_verse_4.mp3', '', 1761754199, 1761754199),
