(37189, 'Psalms 129:8', 'Psalms', 129, 8, 'نه دې هېڅ یو لاروی ووایي چې څښتن دې تاته برکت درکړي یا د څښتن په نوم تاته برکت درکوم', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/psalms129_verse_8.mp3', '', 1761754199, 1761754199),
(37190, 'Deuteronomy 16:1', 'Deuteronomy', 16, 1, 'د ابیب په میاشت کې خپل څښتن خدای ته د فسحې د اختر په لمانځلو سره د هغه درناوی وکړئ، ځکه چې په همدې میاشت کې څښتن د شپې له خوا تاسو د مصر څخه راوویستلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_1.mp3', '', 1761754199, 1761754199),
(37191, 'Deuteronomy 16:2', 'Deuteronomy', 16, 2, 'د فسحې د اختر قرباني باید ستاسو د پادې یا رمې څخه یو حیوان وي او تاسو باید دا په هغه ځای کې خپل څښتن خدای ته وړاندې کړئ چې هغه یې د خپل عبادت دپاره غوره کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_2.mp3', '', 1761754199, 1761754199),
(37192, 'Deuteronomy 16:3', 'Deuteronomy', 16, 3, 'کله چې تاسو د قربانۍ غوښه خورئ، داسې ډوډۍ ورسره مه خورئ چې خمیره ولري. اووه ورځې باید تاسو د هغه وخت په شان فطیره ډوډۍ وخورئ کله چې تاسو په بیړه د مصر څخه وتلئ. دا ډوډۍ وخورئ، دا به د ځورېدلو د ډوډۍ په نوم یاده شي، نو ترڅو پورې چې تاسو ژوندي یئ، هغه ورځ به مو په یاد وي چې تاسو د مصر یعنې د ځورېدلو د ځای څخه راووتلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_3.mp3', '', 1761754199, 1761754199),
(37193, 'Deuteronomy 16:4', 'Deuteronomy', 16, 4, 'ستاسو په ټوله خاوره کې باید هېڅوک اووه ورځې خمیره ونه لري او د هغه حیوان غوښه چې د اولې ورځې په ماښام حلال شوی وي، باید په هماغه شپه وخوړل شي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_4.mp3', '', 1761754199, 1761754199),
(37194, 'Deuteronomy 16:5', 'Deuteronomy', 16, 5, 'تاسو باید د فسحې د اختر قرباني په هېڅ ښار کې چې خپل څښتن خدای یې درکوي وړاندې نه کړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_5.mp3', '', 1761754199, 1761754199),
(37195, 'Deuteronomy 16:6', 'Deuteronomy', 16, 6, 'دا قرباني باید یوازې په هغه ځای کې وړاندې شي چې څښتن یې د خپل عبادت دپاره غوره کوي. د قربانۍ حیوان د لمرپرېواته په وخت کې حلال کړئ، ځکه چې تاسو د مصر څخه د لمرپرېواته په وخت کې راووتلئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_6.mp3', '', 1761754199, 1761754199),
(37196, 'Deuteronomy 16:7', 'Deuteronomy', 16, 7, 'بیا د هغه غوښه پخه کړئ او د عبادت په ځای کې یې وخورئ او سهار خپلو خېمو ته ستانه شئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_7.mp3', '', 1761754199, 1761754199),
(37197, 'Deuteronomy 16:8', 'Deuteronomy', 16, 8, 'په راتلونکو شپږو ورځو کې باید فطیره ډوډۍ وخورئ او په اوومه ورځ د خپل څښتن خدای د عبادت دپاره راټول شئ او په هغه ورځ هېڅ کار مه کوئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_8.mp3', '', 1761754199, 1761754199),
(37198, 'Deuteronomy 16:9', 'Deuteronomy', 16, 9, 'د هغه وخت څخه چې تاسو د غلو دانو رېبل پیل کوئ، اووه هفتې وشمېرئ', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_9.mp3', '', 1761754199, 1761754199),
(37199, 'Deuteronomy 16:12', 'Deuteronomy', 16, 12, 'تاسو به په غور سره د دغو امرونو اطاعت کوئ. دا خبره مه هېروئ چې تاسو په مصر کې غلامان وئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_12.mp3', '', 1761754199, 1761754199),
(37200, 'Deuteronomy 16:13', 'Deuteronomy', 16, 13, 'کله چې تاسو خپلې غلې دانې غوبل کړلې او خپل انګور مو د شربت ویستلو په خم کې وزبېښل، اووه ورځې د جونګړو اختر ولمانځئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_13.mp3', '', 1761754199, 1761754199),
(37201, 'Deuteronomy 16:14', 'Deuteronomy', 16, 14, 'د خپلو اولادونو او نوکرانو او د هغو لاویانو، پردیو خلکو، یتیمانو او کونډو سره چې ستاسو په ښارونو کې اوسیږي په دې اختر کې خوشحالي وکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_14.mp3', '', 1761754199, 1761754199),
(37202, 'Deuteronomy 16:15', 'Deuteronomy', 16, 15, 'په هغه ځای کې چې څښتن یې د خپل عبادت دپاره غوره کوي، اووه ورځې د دې اختر په لمانځلو سره د خپل څښتن خدای درناوی وکړئ. تاسو به ډېر خوشحاله شئ، ځکه چې څښتن به ستاسو په ټولو حاصلاتو او په هر کار کې برکت واچوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_15.mp3', '', 1761754199, 1761754199),
(37203, 'Deuteronomy 16:16', 'Deuteronomy', 16, 16, 'په هر کال کې درې اخترونه دي چې باید ټول نارینه اسراییلیان په کې هغه ځای ته لاړ شي چې څښتن یې د خپل عبادت دپاره غوره کوي. هغه اخترونه دا دي: د فسحې اختر، د لو کولو اختر او د جونګړو اختر. هېڅوک دې څښتن ته تش لاس نه ورځي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_16.mp3', '', 1761754199, 1761754199),
(37204, 'Deuteronomy 16:17', 'Deuteronomy', 16, 17, 'څومره چې هغه حاصلات چې څښتن درکړي دي ډېر وي، هغومره باید ستاسو سوغات غټ وي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_17.mp3', '', 1761754199, 1761754199),
(37205, 'Deuteronomy 16:18', 'Deuteronomy', 16, 18, 'د خپلې هرې قبیلې دپاره په هر ښار کې چې ستاسو څښتن خدای یې تاسو ته درکوي، قاضیان او نور مامورین وټاکئ. هغوی دې په خلکو باندې د انصاف له مخې قضاوت کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_18.mp3', '', 1761754199, 1761754199),
(37206, 'Deuteronomy 16:19', 'Deuteronomy', 16, 19, 'هغوی دې په خپلو قضاوتونو کې بې انصافي یا طرفداري نه کوي او رشوت دې نه اخلي، ځکه چې رشوت حتی د پوهو او صادقانو خلکو سترګې هم ړندوي او د دې سبب ګرځي چې هغوی غلطې پرېکړې واوروي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_19.mp3', '', 1761754199, 1761754199),
(37207, 'Deuteronomy 16:20', 'Deuteronomy', 16, 20, 'تل عادل او باانصافه اوسئ، ترڅو تاسو هغه خاوره ونیسئ چې خپل څښتن خدای یې درکوي او هلته خپل ژوند ته دوام ورکړئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_20.mp3', '', 1761754199, 1761754199),
(37208, 'Deuteronomy 16:21', 'Deuteronomy', 16, 21, 'کله چې تاسو خپل څښتن خدای ته د قربانۍ ځای جوړوئ، د هغه په څنګ کې د لرګیو د اشیره بت مه ودروئ.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_21.mp3', '', 1761754199, 1761754199),
(37209, 'Deuteronomy 16:22', 'Deuteronomy', 16, 22, 'همدارنګه د بت پرستۍ دپاره تیږې مه ودروئ، ځکه چې څښتن د دغو شیانو څخه کرکه کوي.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/deuteronomy16_verse_22.mp3', '', 1761754199, 1761754199),
(37210, 'Zephaniah 1:1', 'Zephaniah', 1, 1, 'د مالِک خُدائ کلام په صفنياه نازل شو. صفنياه د کوشى زوئ او کوشى د جدلياه زوئ، او جدلياه د امرياه زوئ، او امرياه د حزقياه زوئ وو، دا کلام په هغه وخت نازل شو کله چې يوسياه د امون زوئ د يهوداه بادشاه وو.', '', 'OT', 'afghan2023', 'afghan', 'afghan2023/ot/zephaniah1_verse_1.mp3', '', 1761754199, 1761754199);